(()=>{
 const desktop=window.orbitDesktop,release=()=>document.documentElement.classList.remove('orbit-welcome-pending');if(!desktop?.claimWelcome||['#pdf','#browser'].includes(location.hash)){release();return;}
 let dialog=null,skipped=false;
 function close(immediate=false){release();if(!dialog)return;const current=dialog;dialog=null;if(immediate||matchMedia('(prefers-reduced-motion: reduce)').matches){current.close();current.remove();return;}current.classList.add('leaving');setTimeout(()=>{current.close();current.remove();},220);}
 desktop.onOpenPage?.(page=>{if(page?.url||['pdf','browser'].includes(page?.id)){skipped=true;close(true);}});window.addEventListener('hashchange',()=>{if(['#pdf','#browser'].includes(location.hash)){skipped=true;close(true);}});
 desktop.claimWelcome().then(result=>{
  if(!result.ok||!result.show||skipped||['#pdf','#browser'].includes(location.hash)){release();return;}
  const en=result.language!=='zh',copy=en?{title:'Welcome to Orbit.',subtitle:'A calmer space for your day.',start:'Get started',close:'Close',features:[['Read with ChatGPT.','Keep your PDF beside ChatGPT, with automatic PDF attachment and a resizable split.'],['Your day, at a glance.','Optional Gmail and Calendar summaries, local plans and meeting reminders on one home screen.'],['A workspace you can shape.','Pin and categorize workspaces, save text/image favorites, and use the optional local API / MCP bridge.']]}:{title:'欢迎来到 Orbit。',subtitle:'更从容的空间，让每一天更专注。',start:'开始使用',close:'关闭',features:[['与 ChatGPT 一起阅读。','PDF 与 ChatGPT 并排阅读，自动附加当前 PDF，自由调整分屏宽度。'],['一天安排，一目了然。','在一个主页查看可选的 Gmail 与日历摘要、本地计划和会议提醒。'],['由你塑造的工作空间。','置顶与分类工作台，收藏文字和图片，并可选用本地 API / MCP 桥接。']]};
  dialog=document.createElement('dialog');dialog.id='orbit-welcome';dialog.dataset.userContent='';dialog.lang=en?'en':'zh-CN';dialog.setAttribute('aria-labelledby','welcome-title');dialog.innerHTML='<div class="welcome-inner"><img class="welcome-mark" src="assets/welcome-logo.png" alt=""><h1 id="welcome-title"></h1><p class="welcome-subtitle"></p><div class="welcome-features"></div><button class="welcome-start" type="button"></button></div>';
  dialog.querySelector('h1').textContent=copy.title;dialog.querySelector('.welcome-subtitle').textContent=copy.subtitle;
  copy.features.forEach(([title,description],i)=>{const card=document.createElement('article');card.style.setProperty('--order',i);const number=document.createElement('span'),heading=document.createElement('h2'),body=document.createElement('p');number.className='welcome-number';number.textContent='0'+(i+1);heading.textContent=title;body.textContent=description;card.append(number,heading,body);dialog.querySelector('.welcome-features').append(card);});
  const start=dialog.querySelector('.welcome-start');start.textContent=copy.start;start.onclick=async()=>{if(start.disabled)return;start.disabled=true;try{const result=await desktop.completeWelcome();if(!result.ok)throw Error('Welcome could not be saved');close();}catch{start.disabled=false;let error=dialog.querySelector('.welcome-error');if(!error){error=document.createElement('p');error.className='welcome-error';error.setAttribute('role','alert');start.after(error);}error.textContent=en?'Could not save your welcome preference. Please try again.':'无法保存欢迎设置，请重试。';}};dialog.addEventListener('cancel',event=>event.preventDefault());document.body.append(dialog);dialog.showModal();start.focus({preventScroll:true});
 }).catch(()=>release());
})();
